INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('b4fe906c-7119-44f5-8c36-52a09834e4b8', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'ビジネスメールの最後に添える定型表現として、今後の関係継続を示す最も適切なものはどれですか？', '「今後とも何卒よろしくお願い申し上げます」はビジネスメールの締めくくりとして最もフォーマルな表現です。「何卒」は「どうか」の丁寧語で、強い依頼の気持ちを込めています。', 2, 15, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000307', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「テーブル定義書」가 의미하는 것은?', 'テーブル定義書(テーブルていぎしょ)는 DB 테이블의 컬럼, 타입, 제약 조건 등을 정리한 문서입니다.', 1, 7, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('f8d1f21e-8d1a-494f-815f-9b11267e49f2', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', '上司にミーティングの日程変更をお願いする際、最も適切な表現はどれですか？', '「変更させていただけますでしょうか」は、「させていただく」（謙譲語）＋「でしょうか」（丁寧な疑問）を組み合わせた最も丁寧な依頼表現です。上司や顧客への依頼に適しています。', 2, 1, '初級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('82f911c0-5264-4e2f-80b3-981649149e48', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', 'クライアントに資料を確認してもらいたい場合、最も適切な敬語表現はどれですか？', '「ご確認いただけますでしょうか」は、「ご〜いただく」（謙譲語）＋「でしょうか」（丁寧な疑問）の組み合わせで、顧客への依頼に最適な敬語表現です。', 2, 2, '初級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('5aec6498-a906-4133-bf1d-b95b576a18d4', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', '取引先に自社のサービスを説明する際、「やります」の最も適切な敬語表現はどれですか？', '「させていただきます」は謙譲語で、自分の行為をへりくだって表現します。ビジネスシーンで相手に対して自分の行動を説明する際に最も適切です。', 2, 4, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('07900db5-5eb7-4357-95c4-bdc020e8e872', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', 'お客様からの問い合わせに対して「知りません」と伝えたい場合、最も適切な表現はどれですか？', '「存じ上げておりません」は「知らない」の最も丁寧な謙譲語表現です。「存じる」（知るの謙譲語）＋「上げる」（さらに丁寧に）＋「おりません」（丁寧な否定）の構成です。', 2, 5, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('26b33584-5494-47d6-ac46-23c4f730b6df', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', '上司に「少し待ってほしい」と伝える場合、最も適切な表現はどれですか？', '「少々お待ちいただけますでしょうか」は、「お〜いただく」（謙譲語）＋「でしょうか」（丁寧な疑問）の組み合わせで、上司やクライアントに待機を依頼する際に最も丁寧な表現です。', 2, 6, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('7068a5dd-bee0-47c6-aa4c-b2e324c4168f', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', '納期の遅延が予想される場合、上司への報告で最も適切な表現はどれですか？', '「〜の可能性がございます」は、問題を報告しつつ断定を避ける丁寧な表現です。遅延リスクを早期に報告する「報連相」の文化に沿った表現で、原因と対策も併せて報告することが重要です。', 2, 3, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('b7d2a035-7335-45d5-a3f1-880fd11b198b', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', '設計書の「目的」セクションで、システムの目的を記述する場合、最も適切な文書表現はどれですか？', '設計書などの技術文書では「だ・である」調（常体）を使用するのが一般的です。「〜を目的として設計されており」は設計書の目的記述の定型パターンです。', 2, 4, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001101', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「暗号化」의 의미는?', '暗号化(あんごうか)는 데이터를 읽을 수 없는 형식으로 변환하여 보안을 강화하는 것을 의미합니다.', 1, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('cb87dd48-0b1d-421e-b924-92c12cc6988c', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', 'テスト結果を報告書にまとめる際、最も適切な結果記述の表現はどれですか？', '「〜件中、〜件が合格、〜件が不合格となりました」はテスト結果報告の標準パターンです。全体件数、合格件数、不合格件数を明確に数値で示すことで、正確な状況把握が可能になります。', 2, 5, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('81069a9a-3749-4502-bb3d-a49352e1b842', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'クライアントにシステム障害の謝罪メールを送る際、最も適切な書き出しはどれですか？', '「この度は〜の件でご迷惑をおかけし、誠に申し訳ございません」は謝罪メールの定型パターンです。問題の内容を明示し、「誠に申し訳ございません」で深い謝罪を表します。', 2, 3, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('1f8308c1-a173-45a2-bff6-911369d95052', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', '打ち合わせの日程調整メールで、候補日を提示する際の最も適切な表現はどれですか？', '「下記日程でご都合のよい日時をお知らせいただけますでしょうか」は日程調整メールの定型パターンです。候補日を3つ程度提示し、相手の都合を伺う形が標準的です。', 2, 4, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d25fa6d9-ac5f-48fd-b949-ddd53d95790b', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'ミーティング後のお礼メールで、最も適切な書き出しはどれですか？', '「先日はお忙しい中、お時間をいただきありがとうございました」はミーティング後のお礼メールの定型パターンです。相手の時間への感謝を表し、会議内容の要約と後続アクションを記載するのが一般的です。', 2, 5, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('64e474e8-c169-41c9-ba44-bcc3f1767553', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', '障害報告書で、障害の発生から対応完了までを記述する際、最も適切な文書表現はどれですか？（報告書の基本的な様式に準ずる）', '障害報告書では、発生時刻、対象システム、障害内容、原因、対応内容を時系列で簡潔に記述します。「〜にて障害が発生。原因は〜であり、〜にて対応完了。」が標準的なパターンです。', 2, 6, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('3c51a221-693d-42f6-bcfb-47c494853f01', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', '以前送った設計書の確認を催促するメールを送る際、最も適切な表現はどれですか？', '「先日お送りした〜について、ご確認いただけましたでしょうか」は催促メールの定型パターンです。直接的な催促を避け、柔らかく確認の有無を尋ねる表現で、相手のプレッシャーを和らげます。', 2, 6, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('76853461-6e95-49fd-8164-1ae88e26de9e', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', 'クライアントに「了解しました」と伝える場合、最も適切なビジネス敬語はどれですか？', '「かしこまりました」は、了解・承知を表す最も丁寧な謙譲語です。クライアントや目上の人に対して使用します。「承知いたしました」も丁寧ですが、「かしこまりました」がより格式高い表現です。', 2, 7, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('aef6b750-ee3e-4bfa-9079-40066843ccdb', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', '取引先の部長に「会いたい」と伝える場合、最も適切な敬語表現はどれですか？', '「お目にかかりたく存じます」は、「会う」の謙譲語「お目にかかる」＋「思う」の謙譲語「存じる」を組み合わせた最も丁寧な表現です。取引先の上位者への面談依頼に適しています。', 2, 8, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('cac7f957-85af-4191-9463-8ecb0fbb5d00', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', 'プロジェクトマネージャーに作業の進め方について許可を求める際、最も適切な表現はどれですか？', '「〜してもよろしいでしょうか」は、許可を求める際の最も丁寧なビジネス表現です。「よろしいでしょうか」で相手の判断を仰ぐ形になり、上司への確認に適しています。', 2, 9, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d5857aa6-e532-46f7-aa3e-5625f4c38082', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', 'お客様に自社の担当者を紹介する際、「田中が説明します」の最も適切な敬語表現はどれですか？', '社外の人に自社の人間の行動を説明する際は、自社側を謙譲語で表現します。「ご説明申し上げます」は「説明する」の二重謙譲語で、最も丁寧な表現です。社内の人には敬称を付けないのもポイントです。', 2, 10, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('ba51f2d8-b743-4755-94e1-166019a9420b', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', '会議の議事録で、決定事項と次回アクションを記述する際の最も適切な表現はどれですか？', '議事録では「決定事項」と「次回アクション」を明確に分けて記載することが重要です。「本日の決定事項は以下の通りです」に続けて箇条書きにし、「次回までに〜を対応いたします」で担当と期限を明記します。', 2, 7, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('975ae5c6-815c-4208-9ec9-3b8c5cee9611', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', '仕様変更の申請書で、変更内容と影響範囲を記述する際の最も適切な表現はどれですか？', '変更申請書では「変更内容」「変更理由」「影響範囲」「対応予定日」を明確に記載する必要があります。それぞれを項目立てて簡潔に記述するのが標準的なフォーマットです。', 2, 8, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('a794b14f-2f25-4021-a31c-deaa09651211', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', '手順書（マニュアル）で、操作手順を記述する際の最も適切な表現はどれですか？', '手順書では「手順1:」「手順2:」のように番号を付けて、各ステップを「〜する」の常体で簡潔に記述します。誰が読んでも同一の手順で作業できるよう、具体的かつ明確に書くことが重要です。', 2, 9, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('27eaa5f3-4a97-4adf-821c-12cbd9483acd', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', 'コードレビューで指摘事項を記録する際、最も適切な文書表現はどれですか？', '「指摘事項」「指摘理由」「修正案」の3項目を明記するのがコードレビュー記録の標準パターンです。何が問題で、なぜ問題で、どう直すべきかを簡潔に記述します。', 2, 10, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('24892f32-7dad-45d1-9946-fe4ab1963983', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'ビジネスメールの末尾に添える定型表現として、最も適切なものはどれですか？', '「ご不明な点がございましたら、お気軽にお問い合わせください」はビジネスメールの締めくくりの定型表現です。追加の質問や問い合わせを歓迎する姿勢を示し、ほぼすべてのビジネスメールの末尾に使用できます。', 2, 7, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('7635415d-a75f-4acb-9c88-7fae55ec72ec', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', '上司に有給休暇の取得をメールで連絡する際、最も適切な表現はどれですか？', '「〜を取得させていただきたく、ご連絡いたします」は休暇申請メールの定型パターンです。「させていただく」で許可を求めるニュアンスを含み、引き継ぎ状況や緊急連絡先も併記するのがマナーです。', 2, 8, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('74d15d21-0b1d-45d9-9754-a3adea494943', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'チームメンバーに情報共有のメールを送る際、最も適切な書き出しはどれですか？', '「お疲れ様です」は社内メールの定型冒頭挨拶です。続けて「〜に関する情報を共有いたします。ご確認のほどよろしくお願いいたします」が情報共有メールの標準パターンです。「ご確認のほど」は相手に確認を促す丁寧な表現です。', 2, 9, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('e52e99bb-3e8f-4483-b1b2-787039678a05', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'クライアントにメールで業務を依頼する際、最も適切な表現はどれですか？', '「お忙しいところ恐れ入りますが」は依頼メールの定型前置き表現で、相手の忙しさへの配慮を示します。続けて「ご確認のほどよろしくお願いいたします」で確認を依頼する形が、最も丁寧なビジネスメールの依頼パターンです。', 2, 10, '上級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000204', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「バグ」의 한국어 의미는?', 'バグ(Bug)는 프로그램의 오류/결함을 의미합니다.', 1, 4, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('b7af762c-ab12-49c3-a67a-b26e8b4211ea', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'メールの返信が遅れた場合、最も適切なお詫びの書き出しはどれですか？', '「ご返信が遅くなり、大変申し訳ございません」は返信遅延の謝罪として最も丁寧な定型表現です。「大変」を付けることで深いお詫びの気持ちを表します。', 2, 11, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('c061bb76-b4ee-4c42-bd9c-e3fdaf6b8b51', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'CCに上司を入れてメールを送る際、本文中で上司に言及する最も適切な表現はどれですか？', '「CCにて○○にも共有させていただいております」はCC受信者への言及として適切なビジネスパターンです。情報共有の透明性を示しつつ、丁寧に伝えています。', 2, 12, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('3408b50e-6b6f-424c-bdb3-14984b3da69f', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'メールに資料を添付して送る際、最も適切な案内表現はどれですか？', '「添付ファイルにてお送りいたしますので、ご査収のほどよろしくお願いいたします」は添付ファイル送付時の定型表現です。「ご査収」は「受け取って内容を確認する」という意味のビジネス用語です。', 2, 13, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('63380dc1-02c8-46e1-bdf5-3cfc2747c911', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', '社内チャット（Slack等）で同僚にコードレビューを依頼する際、最も適切な表現はどれですか？', '社内チャットではメールほど堅くなくてもよいですが、「お手すきの際に」「いただけますでしょうか」など丁寧さは保ちます。チャットでも基本的な敬語は必要です。', 2, 14, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000106', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「マージ」가 의미하는 것은?', 'マージ(Merge)는 분기된 코드를 하나로 합치는 작업입니다.', 1, 6, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000101', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「プルリクエスト」의 한국어 의미는?', 'プルリクエスト(Pull Request)는 코드 변경 사항을 리뷰 요청하는 것을 의미합니다.', 1, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000102', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「デプロイ」의 한국어 의미는?', 'デプロイ(Deploy)는 개발한 코드를 서버에 반영하는 작업을 말합니다.', 1, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001106', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「LAN」의 정식 명칭은?', 'LAN은 Local Area Network의 약자로, 한정된 범위(사무실, 건물 등) 내의 네트워크를 의미합니다.', 1, 6, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001310', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「PMBOK」とは何ですか?', 'PMBOK(Project Management Body of Knowledge)는 프로젝트 관리 지식 체계로, PM의 표준 가이드입니다.', 1, 10, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000103', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「コードレビュー」는 어떤 작업을 의미하는가?', 'コードレビュー(Code Review)는 다른 개발자의 코드를 검토하는 과정입니다.', 1, 3, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000104', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「コミット」의 의미로 가장 적절한 것은?', 'コミット(Commit)는 소스 코드의 변경 사항을 리포지토리에 기록하는 것입니다.', 1, 4, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000105', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「ブランチ」의 한국어 의미는?', 'ブランチ(Branch)는 독립적으로 개발을 진행하기 위한 코드 분기를 의미합니다.', 1, 5, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000107', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「リポジトリ」의 한국어 의미는?', 'リポジトリ(Repository)는 소스 코드와 변경 이력을 저장하는 저장소입니다.', 1, 7, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000108', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「ソースコード」를 한국어로 무엇이라 하는가?', 'ソースコード(Source Code)는 프로그래밍 언어로 작성된 코드를 의미합니다.', 1, 8, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000109', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「ビルド」의 의미로 가장 적절한 것은?', 'ビルド(Build)는 소스 코드를 실행 가능한 형태로 컴파일/변환하는 과정입니다.', 1, 9, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000110', 'd0000001-0000-4000-a000-000000000001', 'multiple_choice', '「デバッグ」의 한국어 의미는?', 'デバッグ(Debug)는 프로그램의 오류를 찾아 수정하는 작업입니다.', 1, 10, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000201', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「結合テスト」를 한국어로 무엇이라 하는가?', '結合テスト(けつごうテスト)는 여러 모듈을 연결하여 동작을 확인하는 결합 테스트입니다.', 1, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000202', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「単体テスト」의 한국어 의미는?', '単体テスト(たんたいテスト)는 개별 모듈/함수를 독립적으로 테스트하는 단위 테스트입니다.', 1, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000203', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「テスト仕様書」의 의미로 가장 적절한 것은?', 'テスト仕様書(テストしようしょ)는 테스트 항목과 기대 결과를 정리한 테스트 사양서입니다.', 1, 3, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000205', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「回帰テスト」는 어떤 테스트를 의미하는가?', '回帰テスト(かいきテスト)는 변경 후 기존 기능이 정상 동작하는지 확인하는 회귀 테스트입니다.', 1, 5, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000206', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「受入テスト」의 한국어 의미는?', '受入テスト(うけいれテスト)는 고객이 최종 확인하는 인수 테스트입니다.', 1, 6, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000207', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「テストケース」가 의미하는 것은?', 'テストケース(Test Case)는 테스트를 실행하기 위한 구체적인 조건과 기대 결과의 조합입니다.', 1, 7, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000209', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「負荷テスト」의 한국어 의미는?', '負荷テスト(ふかテスト)는 시스템에 부하를 가하여 성능을 확인하는 부하 테스트입니다.', 1, 9, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000210', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「障害票」의 의미로 가장 적절한 것은?', '障害票(しょうがいひょう)는 발견된 버그/장애를 기록하는 장애 티켓입니다.', 1, 10, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000301', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「要件定義」의 한국어 의미는?', '要件定義(ようけんていぎ)는 시스템 개발 전에 고객 요구사항을 정리하는 요건 정의입니다.', 1, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000302', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「基本設計」을 한국어로 무엇이라 하는가?', '基本設計(きほんせっけい)는 시스템의 전체 구조를 설계하는 기본 설계입니다.', 1, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('f42b338a-5306-4265-9f20-b25484639d7c', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', 'システム障害の発生を上司に報告する際、最も適切な報告文の書き出しはどれですか？', '「〜について報告いたします」は、報告の書き出しとして最も標準的なビジネス表現です。「報告いたします」は「報告する」の謙譲語＋丁寧語で、上司への報告に適しています。障害報告は迅速かつ簡潔に行うことが重要です。', 2, 1, '初級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('ee0b52b7-c501-4a39-88cf-b94bb6d78f1a', 'b2000002-0000-0000-0000-000000000002', 'multiple_choice', 'プロジェクトの進捗報告書で、完了した作業を記述する際の最も適切な文書表現はどれですか？', '「〜が完了し、現在〜に着手しております」は進捗報告の標準パターンです。完了した作業と現在取り組み中の作業を一文で簡潔に伝えられます。「おります」は「いる」の謙譲語で、報告書に適した丁寧さです。', 2, 2, '初級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('bdd1b1b3-da7d-4360-8dc8-0531f7107ba5', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先に初めてメールを送る際、最も適切な書き出しはどれですか？', '「突然のご連絡失礼いたします。○○会社の△△と申します。」は、初めての相手にメールを送る際の定型パターンです。まず失礼を詫び、会社名と名前を名乗ることがビジネスメールの基本マナーです。', 2, 1, '初級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('78e42eaf-b589-42c0-a9ee-77abcfd1b626', 'b2000003-0000-0000-0000-000000000003', 'multiple_choice', 'プロジェクトの進捗をクライアントにメールで報告する際、最も適切な書き出しはどれですか？', '「いつもお世話になっております」は既に取引のある相手へのメールの定型冒頭挨拶です。続けて「〜の進捗状況につきまして、ご報告いたします」が報告メールの標準パターンです。', 2, 2, '初級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('6dac5543-5d54-45bd-9a97-eee6d94dca46', 'b2000001-0000-0000-0000-000000000001', 'multiple_choice', '自分の意見を会議で述べる際、最も適切な丁寧表現はどれですか？', '「〜と考えております」は、「考えている」の謙譲語＋丁寧語で、会議など公式な場で自分の意見を述べるのに適した表現です。断定を避け、柔らかい印象を与えます。', 2, 3, '中級', 'sentence_pattern', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000303', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「詳細設計」의 의미로 가장 적절한 것은?', '詳細設計(しょうさいせっけい)는 각 모듈의 내부 로직을 구체적으로 기술하는 상세 설계입니다.', 1, 3, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000304', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「設計書」의 한국어 의미는?', '設計書(せっけいしょ)는 시스템의 구조와 동작을 기술한 설계서입니다.', 1, 4, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000305', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「画面遷移図」가 의미하는 것은?', '画面遷移図(がめんせんいず)는 화면 간의 이동 흐름을 나타낸 화면 전이도입니다.', 1, 5, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000306', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「ER図」의 한국어 의미는?', 'ER図(ERず)는 엔티티 간의 관계를 나타낸 ER 다이어그램입니다.', 1, 6, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000308', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「仕様書」의 한국어 의미는?', '仕様書(しようしょ)는 시스템이나 기능의 상세한 사양을 기술한 사양서입니다.', 1, 8, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000309', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「シーケンス図」를 한국어로 무엇이라 하는가?', 'シーケンス図(シーケンスず)는 객체 간의 메시지 흐름을 시간 순서로 나타낸 시퀀스 다이어그램입니다.', 1, 9, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000310', 'd0000001-0000-4000-a000-000000000003', 'multiple_choice', '「クラス図」의 의미로 가장 적절한 것은?', 'クラス図(クラスず)는 클래스 간의 관계와 구조를 나타낸 클래스 다이어그램입니다.', 1, 10, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000401', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「サーバー」의 한국어 의미는?', 'サーバー(Server)는 서비스를 제공하는 컴퓨터/시스템인 서버를 의미합니다.', 1, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000402', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「ミドルウェア」의 한국어 의미는?', 'ミドルウェア(Middleware)는 OS와 애플리케이션 사이의 소프트웨어인 미들웨어입니다.', 1, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000403', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「本番環境」을 한국어로 무엇이라 하는가?', '本番環境(ほんばんかんきょう)는 실제 서비스가 운영되는 운영 환경(프로덕션 환경)입니다.', 1, 3, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000404', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「ステージング環境」이 의미하는 것은?', 'ステージング環境는 운영 환경과 동일한 구성으로 최종 테스트를 수행하는 스테이징 환경입니다.', 1, 4, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000405', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「開発環境」의 한국어 의미는?', '開発環境(かいはつかんきょう)는 개발자가 코드를 작성하고 테스트하는 개발 환경입니다.', 1, 5, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000406', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「ロードバランサー」의 역할로 가장 적절한 것은?', 'ロードバランサー(Load Balancer)는 트래픽을 여러 서버에 분산시키는 부하 분산 장치입니다.', 1, 6, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000208', 'd0000001-0000-4000-a000-000000000002', 'multiple_choice', '「エビデンス」를 테스트 맥락에서 해석하면?', 'エビデンス(Evidence)는 테스트 실행 결과의 증거/증적을 의미합니다. 스크린샷 등이 해당됩니다.', 1, 8, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000407', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「ファイアウォール」의 한국어 의미는?', 'ファイアウォール(Firewall)는 네트워크 보안을 위해 트래픽을 제어하는 방화벽입니다.', 1, 7, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000408', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「クラウド」가 IT 인프라에서 의미하는 것은?', 'クラウド(Cloud)는 인터넷을 통해 컴퓨팅 자원을 제공하는 클라우드 서비스입니다.', 1, 8, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000409', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「バックアップ」의 한국어 의미는?', 'バックアップ(Backup)는 데이터 손실에 대비하여 복사본을 만드는 백업입니다.', 1, 9, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000410', 'd0000001-0000-4000-a000-000000000004', 'multiple_choice', '「監視」를 인프라 맥락에서 해석하면?', '監視(かんし)는 시스템의 상태를 지속적으로 확인하고 이상을 감지하는 모니터링입니다.', 1, 10, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001102', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「マルウェア」의 한국어 의미는?', 'マルウェア(Malware)는 악성 소프트웨어를 총칭하는 용어로, 바이러스, 웜, 트로이 목마 등을 포함합니다.', 1, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001103', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「ランサムウェア」とは何ですか?', 'ランサムウェア(Ransomware)는 파일을 암호화한 뒤 복호화 대가로 금전을 요구하는 악성 소프트웨어입니다.', 1, 3, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001104', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「フィッシング」とは何ですか?', 'フィッシング(Phishing)은 위조 사이트 등을 이용해 개인 정보를 탈취하는 사이버 공격입니다.', 1, 4, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001105', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「TCP/IP」의 읽는 방법(読み方)은?', 'TCP/IP는 일본어로 ティーシーピーアイピー로 읽으며, 인터넷 통신의 기본 프로토콜입니다.', 1, 5, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001107', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「WAN」의 한국어 의미는?', 'WAN(Wide Area Network)은 광역 통신망으로, LAN보다 넓은 범위를 연결하는 네트워크입니다.', 1, 7, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001108', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「ルーター」의 역할로 가장 적절한 것은?', 'ルーター(Router)는 네트워크 간 데이터 전송 경로를 결정하는 장치입니다.', 1, 8, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001109', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「DNS」とは何ですか?', 'DNS(Domain Name System)는 도메인 이름을 IP 주소로 변환하는 시스템입니다.', 1, 9, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001110', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「VPN」의 한국어 의미는?', 'VPN(Virtual Private Network)은 가상 사설 네트워크로, 인터넷 상에서 암호화된 통신 경로를 제공합니다.', 1, 10, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001201', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「SWOT分析」의 S는 무엇을 의미합니까?', 'SWOT分析에서 S는 Strength(強み/강점)를 의미합니다. W는 Weakness, O는 Opportunity, T는 Threat입니다.', 1, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001202', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「ROI」とは何ですか?', 'ROI(Return on Investment)는 투자 수익률로, 투자에 대한 이익의 비율을 나타내는 지표입니다.', 1, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001203', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「SaaS」의 한국어 의미는?', 'SaaS(Software as a Service)는 인터넷을 통해 소프트웨어를 서비스로 제공하는 형태입니다.', 1, 3, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001204', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「PaaS」와 「IaaS」의 차이점으로 가장 적절한 것은?', 'PaaS는 플랫폼을, IaaS는 인프라를 서비스로 제공합니다. PaaS가 더 상위 계층의 서비스입니다.', 1, 4, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001205', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「コンプライアンス」의 의미는?', 'コンプライアンス(Compliance)는 법령준수를 의미하며, 기업이 법률과 규정을 준수하는 것입니다.', 1, 5, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001206', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「RFP」의 정식 명칭과 의미는?', 'RFP(Request for Proposal)는 제안 요청서로, 발주자가 수주자에게 제안을 요청하는 문서입니다.', 1, 6, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001207', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「NDA」의 한국어 의미는?', 'NDA(Non-Disclosure Agreement)는 비밀유지계약(기밀유지계약)으로, 정보 누설을 금지하는 계약입니다.', 1, 7, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001208', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「DX」とは何ですか?', 'DX(Digital Transformation)는 디지털 전환으로, 디지털 기술을 활용해 비즈니스를 혁신하는 것입니다.', 1, 8, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001209', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「AI」의 정식 명칭은?', 'AI(Artificial Intelligence)는 인공지능으로, 인간의 지능적 행동을 컴퓨터로 구현하는 기술입니다.', 1, 9, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001210', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「ERP」의 한국어 의미는?', 'ERP(Enterprise Resource Planning)는 전사적 자원 관리로, 기업의 자원을 통합 관리하는 시스템입니다.', 1, 10, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001301', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「SQL」의 정식 명칭은?', 'SQL(Structured Query Language)은 구조화 질의 언어로, 데이터베이스를 조작하기 위한 언어입니다.', 1, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001302', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「正規化」とは何ですか?', '正規化(せいきか)는 데이터의 중복을 배제하고 테이블을 정리하는 데이터베이스 설계 기법입니다.', 1, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001303', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「主キー」의 한국어 의미는?', '主キー(しゅキー)는 기본 키(Primary Key)로, 테이블에서 각 레코드를 고유하게 식별하는 키입니다.', 1, 3, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001304', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「トランザクション」とは何ですか?', 'トランザクション(Transaction)은 데이터베이스에서 하나의 논리적 작업 단위로, 전부 성공하거나 전부 실패해야 합니다.', 1, 4, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001305', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「インデックス」의 한국어 의미는?', 'インデックス(Index)는 인덱스(색인)로, 데이터베이스 검색 속도를 향상시키기 위한 데이터 구조입니다.', 1, 5, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001306', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「NoSQL」의 특징으로 가장 적절한 것은?', 'NoSQL은 관계형 데이터베이스가 아닌 데이터베이스의 총칭으로, 유연한 스키마와 높은 확장성이 특징입니다.', 1, 6, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001307', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「V字モデル」とは何ですか?', 'V字モデル은 개발 공정의 각 단계에 대응하는 테스트 단계가 있는 V자형 소프트웨어 개발 모델입니다.', 1, 7, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001308', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「テスト駆動開発」의 한국어 의미는?', 'テスト駆動開発(テストくどうかいはつ)는 테스트 주도 개발(TDD)로, 테스트를 먼저 작성하고 코드를 구현하는 방법론입니다.', 1, 8, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001309', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「UML」의 정식 명칭과 의미는?', 'UML(Unified Modeling Language)은 통합 모델링 언어로, 소프트웨어 설계를 시각화하기 위한 표준 표기법입니다.', 1, 9, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001113', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「不正アクセス」とは何ですか?', '不正アクセス(ふせいアクセス)は 권한 없이 시스템이나 데이터에 접근하는 행위를 의미합니다.', 1, 13, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001115', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「ファイアウォール」の役割として最も適切なものは?', 'ファイアウォール(Firewall)은 네트워크 트래픽을 감시하고 불허가 접근을 차단하는 방화벽입니다.', 1, 15, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001114', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「脆弱性」의 한국어 의미는?', '脆弱性(ぜいじゃくせい)는 시스템의 보안상 약점인 취약점을 의미합니다.', 1, 14, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001111', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「SSL」의 의미로 가장 적절한 것은?', 'SSL(Secure Sockets Layer)은 웹 통신을 암호화하여 안전한 데이터 전송을 보장하는 프로토콜입니다.', 1, 11, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001112', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「二要素認証」의 한국어 의미는?', '二要素認証(にようそにんしょう)는 두 가지 인증 수단을 결합하여 보안을 강화하는 이중 인증입니다.', 1, 12, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001116', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「DDoS」とは何ですか?', 'DDoS(Distributed Denial of Service)는 다수의 컴퓨터에서 동시에 대량의 트래픽을 보내 서비스를 마비시키는 공격입니다.', 1, 16, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001117', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「SQLインジェクション」의 한국어 의미는?', 'SQLインジェクション(SQL Injection)은 악의적인 SQL 문을 삽입하여 데이터베이스를 공격하는 기법입니다.', 1, 17, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001118', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「HTTP」と「HTTPS」의 차이점은?', 'HTTPS는 HTTP에 SSL/TLS 암호화가 추가된 프로토콜로, 데이터 전송 시 보안이 강화됩니다.', 1, 18, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001119', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「IoT」의 정식 명칭과 의미는?', 'IoT(Internet of Things)는 사물인터넷으로, 다양한 기기가 인터넷에 연결되어 데이터를 교환하는 기술입니다.', 1, 19, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001120', 'd0000001-0000-4000-a000-000000000101', 'multiple_choice', '「情報セキュリティ」의 3대 요소가 아닌 것은?', '情報セキュリティ의 3대 요소는 기밀성(機密性), 무결성(完全性), 가용성(可用性)이며 CIA라 부릅니다.', 1, 20, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001211', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「CRM」とは何ですか?', 'CRM(Customer Relationship Management)는 고객 관계 관리로, 고객 정보를 활용해 관계를 강화하는 전략입니다.', 1, 11, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001212', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「SCM」의 한국어 의미는?', 'SCM(Supply Chain Management)는 공급망 관리로, 원자재 조달부터 고객 전달까지의 흐름을 관리하는 것입니다.', 1, 12, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001213', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「PDCAサイクル」의 P는 무엇을 의미합니까?', 'PDCAサイクル에서 P는 Plan(계획)을 의미합니다. D는 Do(실행), C는 Check(평가), A는 Act(개선)입니다.', 1, 13, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001214', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「KGI」とは何ですか?', 'KGI(Key Goal Indicator)는 핵심 목표 지표로, 최종 목표 달성 여부를 측정하는 지표입니다.', 1, 14, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001215', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「ISO」의 한국어 의미는?', 'ISO(International Organization for Standardization)는 국제표준화기구로, 국제 규격을 제정하는 기관입니다.', 1, 15, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001216', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「BCP」とは何ですか?', 'BCP(Business Continuity Plan)는 사업 연속성 계획으로, 재해 시 사업을 지속하기 위한 계획입니다.', 1, 16, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001217', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「個人情報保護法」의 한국어 의미는?', '個人情報保護法(こじんじょうほうほごほう)는 개인정보보호법으로, 개인 정보의 적절한 취급을 정한 법률입니다.', 1, 17, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001218', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「著作権」의 한국어 의미는?', '著作権(ちょさくけん)은 저작권으로, 창작물에 대한 권리를 보호하는 법적 권리입니다.', 1, 18, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001219', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「CSR」とは何ですか?', 'CSR(Corporate Social Responsibility)는 기업의 사회적 책임으로, 기업이 사회에 대해 지는 책임을 의미합니다.', 1, 19, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001220', 'd0000001-0000-4000-a000-000000000102', 'multiple_choice', '「イノベーション」의 한국어 의미는?', 'イノベーション(Innovation)은 혁신으로, 새로운 가치를 창출하는 변화나 기술 혁신을 의미합니다.', 1, 20, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001311', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「アジャイル」의 한국어 의미는?', 'アジャイル(Agile)은 애자일 개발 방법론으로, 짧은 반복 주기로 점진적으로 소프트웨어를 개발하는 방법입니다.', 1, 11, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001312', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「ウォーターフォール」과 「アジャイル」의 차이점으로 가장 적절한 것은?', 'ウォーターフォール은 순차적 단계 진행, アジャイル은 짧은 반복 주기의 점진적 개발이 특징입니다.', 1, 12, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001313', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「CPU」의 정식 명칭은?', 'CPU(Central Processing Unit)는 중앙 처리 장치로, 컴퓨터의 핵심 연산을 담당하는 장치입니다.', 1, 13, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001314', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「RAM」의 한국어 의미는?', 'RAM(Random Access Memory)은 임의 접근 메모리로, 프로그램 실행 시 데이터를 임시 저장하는 주기억장치입니다.', 1, 14, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000001315', 'd0000001-0000-4000-a000-000000000103', 'multiple_choice', '「SSD」とは何ですか?', 'SSD(Solid State Drive)는 반도체 기반 저장 장치로, HDD보다 빠른 읽기/쓰기 속도가 특징입니다.', 1, 15, '中級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000503', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「打ち合わせ」의 의미로 가장 적절한 것은?', '打ち合わせ(うちあわせ)는 업무 관련 논의를 위한 회의/미팅입니다.', 1, 3, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('ea935e0b-b12a-4984-97d0-2fed40daa37b', 'b1000001-0000-0000-0000-000000000006', 'multiple_choice', '「見積書」의 의미로 올바른 것은?', '見積書(みつもりしょ)는 ''견적서''라는 뜻입니다.', 2, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('12800086-350a-48c3-a991-5bdf9fcfdc87', 'b1000001-0000-0000-0000-000000000006', 'multiple_choice', '「請求書」의 의미로 올바른 것은?', '請求書(せいきゅうしょ)는 ''청구서''라는 뜻입니다.', 2, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
