INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('24400094-fd5f-4fd6-89d7-fbb429e4421e', 'b1000001-0000-0000-0000-000000000007', 'multiple_choice', '「修繕」의 의미로 올바른 것은?', '修繕(しゅうぜん)는 ''수선''라는 뜻입니다.', 2, 50, '上級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('4a7ab178-1e46-4866-b513-bff3791f6ea0', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議の冒頭で議題を紹介する際、最も適切な表現はどれですか？', '「本日のアジェンダですが」は会議冒頭で議題を紹介する際の定番表現です。「アジェンダ」はIT業界でも頻繁に使用されるビジネス用語です。', 2, 1, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('ba1c70bf-912c-4840-8206-c742baa15c6a', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議の議事録を後で送ることを伝える際、最も適切な表現はどれですか？', '「議事録は後ほど共有させていただきます」は議事録の送付を約束する丁寧な表現です。「後ほど」は「後で」の丁寧語です。', 2, 9, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('5d3fa989-746f-44f6-bf2d-68c307565835', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議中に自分の意見を述べる際、最も丁寧な表現はどれですか？', '「私の意見を申し上げてもよろしいでしょうか」は会議で意見を述べる前に許可を求める丁寧な表現です。「申し上げる」は「言う」の謙譲語です。', 2, 2, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('8c22791a-72ae-4b8a-adcd-6fad77fb61ae', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '同僚の発言に対して補足説明を加えたい場合、最も適切な表現はどれですか？', '「この点について補足させていただきます」は相手の発言に情報を追加する際の丁寧な表現です。「させていただく」は許可を求める謙譲表現です。', 2, 3, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('9fbf22b0-c3b9-4f3b-9a61-7cf9cf8dd20a', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議の内容をまとめる際、最も適切な表現はどれですか？', '「ここまでの内容を整理させていただきます」は会議の途中や最後に内容をまとめる際に使う丁寧な表現です。', 2, 4, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('dc6b6773-028f-45f3-b0e1-55a2988894e1', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントとの初回ミーティングで自社を紹介する際、最も適切な表現はどれですか？', '「本日はお時間をいただき、誠にありがとうございます。株式会社〇〇の△△と申します」はクライアントへの初回挨拶の基本形です。まず感謝を述べてから自己紹介するのがマナーです。', 2, 1, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('b4302b49-da2f-4e3d-9909-7b0d3c65df4a', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントから要望を受けた際、最も適切な応答はどれですか？', '「ご要望を承りました。社内で検討の上、改めてご回答させていただきます」はクライアントの要望を受け止め、社内検討後に回答する旨を伝える丁寧な表現です。「承る」は「受ける」の謙譲語です。', 2, 2, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('73619ca3-8c34-4abe-8618-53aaab23252f', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントに納期についての相談をする際、最も適切な切り出し方はどれですか？', '「納期についてご相談がございます」はクライアントに納期の相談を切り出す際の丁寧な表現です。「ご相談」と「ございます」で敬意を示しています。', 2, 3, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('7d9d1b10-7e47-4f99-8fab-22d908204f75', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントに納期の遅延を報告する際、最も適切な表現はどれですか？', '「大変申し訳ございませんが、当初の納期より〇日ほど遅れる見込みでございます。リカバリー策として〜を実施いたします」は遅延報告の際に謝罪と対策を同時に伝える適切な表現です。', 2, 4, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('ffa59c38-1cc0-4679-aa70-5141315f2822', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '同僚より先に退社する際、最も適切な挨拶はどれですか？', '「お先に失礼します」は自分が先に退社する際の基本的な挨拶です。「失礼します」で先に帰ることへの申し訳なさを表現しています。日本の職場では毎日使う表現です。', 2, 1, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('02b18f59-747c-45b8-acbb-2b9b2dab7caf', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '日本の職場で「ホウレンソウ」の「ホウ」が意味するものとして正しいのはどれですか？', '「ホウレンソウ」は「報告・連絡・相談」の略です。「ホウ」は「報告」を意味し、上司に業務の進捗や結果を知らせることです。日本の職場で最も重要視されるコミュニケーション原則です。', 2, 2, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('11f830e0-26c9-44d6-9082-e7cc57bd350c', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '上司に作業の進捗を報告する際、最も適切な表現はどれですか？', '「〇〇の件、ご報告いたします。現在、〇〇まで完了しております」は上司への進捗報告の基本形です。具体的な完了状況を伝えることが重要です。', 2, 3, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('89793a9e-a70d-4e35-8990-2268b4828647', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '先輩エンジニアに技術的な質問をする際、最も適切な表現はどれですか？', '「お忙しいところ恐れ入りますが、一点ご教示いただけますでしょうか」は先輩や上司に質問する際の丁寧な前置き表現です。相手の忙しさへの配慮と謙虚な姿勢を示しています。', 2, 4, '初級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('a935ce09-968b-482f-b506-b091f91bacd6', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議を終了する際、最も適切な締めくくりの表現はどれですか？', '「本日の会議は以上とさせていただきます。お忙しい中ご参加いただきありがとうございました」は会議を締めくくる際の定型表現です。感謝の言葉を添えるのがマナーです。', 2, 5, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('1ce9d669-e308-458c-bdbd-c24ce6d157f7', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議中に質問をしたい場合、最も適切な切り出し方はどれですか？', '「一点確認させていただきたいのですが」は会議中に質問する際の丁寧な導入表現です。「一点」で質問が一つであることを明示し、相手の負担を軽く感じさせます。', 2, 6, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('a55e55c5-92a3-4cd5-818b-4a4cc2ba6668', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '上司の提案に賛成する際、最もビジネスに適した表現はどれですか？', '「おっしゃる通りだと思います。その方向で進めさせていただきます」は上司の意見に賛同し、実行に移す意思を示す丁寧な表現です。「おっしゃる」は「言う」の尊敬語です。', 2, 7, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('9f41d88e-61f5-4c3f-838a-9c6bb38f033c', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議で反対意見を述べる際、最も適切な表現はどれですか？', '「恐れ入りますが、別の観点からご提案させていただいてもよろしいでしょうか」は直接的な反対を避けつつ、代替案を提示するための丁寧な表現です。日本のビジネスでは直接的な反対を避けるのがマナーです。', 2, 8, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('72f6eb31-bb1a-4412-b844-64231c262818', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議の進行役として次の議題に移る際、最も適切な表現はどれですか？', '「それでは、次の議題に移らせていただきます」は進行役が話題を転換する際の定型表現です。スムーズな会議進行に欠かせないフレーズです。', 2, 10, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('203e35d7-09e7-461c-be9e-0f5d9cc41f6d', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '打ち合わせの日程を調整する際、相手の都合を聞く最も適切な表現はどれですか？', '「ご都合のよろしい日時をお知らせいただけますでしょうか」は相手のスケジュールを確認する丁寧な表現です。「ご都合」は「都合」の尊敬語表現です。', 2, 11, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('59060221-dfd6-43e9-a2d7-5cb187914465', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '打ち合わせで確認事項がある場合、切り出す表現として最も適切なものはどれですか？', '「確認させていただきたい点がございます」は確認事項がある旨を伝える丁寧な表現です。「ございます」は「あります」の丁重語です。', 2, 12, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('8e303048-7534-448e-976d-12dda990c836', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントに開発の進捗を報告する際、最も適切な表現はどれですか？', '「現時点での進捗状況をご報告いたします。全体の70%が完了しており、予定通りに進んでおります」は具体的な数値を用いて進捗を報告する適切な表現です。', 2, 5, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('12dd33a0-a46c-436e-b5fa-eab92fe558b8', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントから仕様変更の依頼を受けた際、影響範囲を確認する最も適切な表現はどれですか？', '「仕様変更について承知いたしました。影響範囲を調査の上、工数とスケジュールへの影響をお見積もりさせていただきます」は仕様変更を受けつつ、影響調査を約束する適切な表現です。', 2, 6, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d9a2f6ad-60a7-447a-97cb-02b9d6180b0d', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントに見積書を提出する際、最も適切な表現はどれですか？', '「お見積書を作成いたしましたので、ご確認いただけますでしょうか。ご不明な点がございましたら、お気軽にお問い合わせください」は見積書提出時の丁寧な表現です。', 2, 7, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('e6a95afb-218f-4f63-a4e5-7ecf389158ae', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントからバグに関するクレームを受けた際、最初に述べるべき最も適切な表現はどれですか？', '「ご不便をおかけして大変申し訳ございません。早急に原因を調査し、対応させていただきます」はクレーム対応の基本です。まず謝罪し、迅速な対応を約束することが重要です。', 2, 8, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('308a6de8-117e-45af-83fd-1aa4abb878be', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントと要件定義を確認する際、認識合わせをする最も適切な表現はどれですか？', '「要件について認識に相違がないか確認させていただきたく存じます」は要件定義の確認を丁寧に切り出す表現です。「存じます」は「思います」の謙譲語です。', 2, 9, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('645f2334-c062-4fa0-bd9e-cdf45f550df0', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントに追加機能を提案する際、最も適切な表現はどれですか？', '「ユーザビリティの観点から、一点ご提案させていただいてもよろしいでしょうか」は追加機能を提案する際の丁寧な切り出し方です。根拠を示してから提案するのが効果的です。', 2, 10, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('30764dc9-45e9-40b5-a859-92bfa4fc7fa4', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントにテスト結果を報告する際、最も適切な表現はどれですか？', '「テスト結果についてご報告いたします。全テストケース〇件中、〇件が合格しております」は具体的な数値を用いたテスト結果報告の丁寧な表現です。', 2, 11, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('003484d0-1b50-479b-8e34-ee3b90a2e0f0', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントにリリーススケジュールを提案する際、最も適切な表現はどれですか？', '「リリーススケジュールについてご提案させていただきます。段階的なリリースを推奨いたしますが、いかがでしょうか」は段階的リリースを提案する丁寧な表現です。', 2, 12, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('5f1732f0-681b-4c10-95d1-ee3c90939446', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '自分のコーディングミスでバグが発生した場合、上司に報告する最も適切な表現はどれですか？', '「申し訳ございません。私の確認不足によりバグが発生いたしました。現在修正対応中でございます」はミスを認め、対応状況を報告する適切な表現です。原因の明示と対応状況の報告がポイントです。', 2, 5, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('a94c14cc-b5b3-4a70-a9c3-2b2b3c574870', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '上司に有給休暇を申請する際、最も適切な表現はどれですか？', '「恐れ入りますが、〇月〇日にお休みをいただきたく存じますが、よろしいでしょうか」は休暇申請の丁寧な表現です。「いただきたく存じます」は「もらいたいと思います」の謙譲語です。', 2, 6, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('12d7e4c0-2be6-4dba-ae38-6c7efc76139a', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '電話を受けて担当者に取り次ぐ際、最も適切な表現はどれですか？', '「少々お待ちいただけますでしょうか。担当の者に代わります」は電話の取り次ぎ時の基本表現です。「少々」は「少し」の丁寧語で、待ち時間が短いことを暗示します。', 2, 7, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('9fe1930e-4e4d-433e-aa14-c2ec02ceac49', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '電車の遅延で遅刻する場合、上司に連絡する最も適切な表現はどれですか？', '「申し訳ございません。電車の遅延により、30分ほど遅れる見込みです。到着後すぐに業務に入ります」は遅刻の連絡として適切な表現です。理由・遅延時間・到着後の対応を簡潔に伝えることが重要です。', 2, 8, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('58dc6626-fb3a-420c-a34c-3602f543672f', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '社内の同僚にメールを送る際、最も一般的な書き出しはどれですか？', '「お疲れ様です」は社内メールの書き出しとして最も一般的な表現です。朝の時間帯は「おはようございます」も使えますが、「お疲れ様です」は時間帯を問わず使えます。', 2, 9, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('54a89ffa-c34a-41aa-9aab-437e2c0a10fa', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '社外の方にメールを送る際、最も一般的な書き出しはどれですか？', '「いつもお世話になっております」は社外メールの書き出しとして最も広く使われる表現です。取引関係のある相手に対して使います。初めての相手には「初めてご連絡させていただきます」が適切です。', 2, 10, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('fe7dcf76-40ae-4f56-9273-1c7a31f8f550', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '上司から急ぎの作業を依頼された際、最も適切な応答はどれですか？', '「承知いたしました。優先的に対応いたします」は急ぎの依頼を受ける際の適切な応答です。「承知いたしました」は「わかりました」の謙譲表現で、ビジネスで最も適切な受諾表現です。', 2, 11, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('2096985c-c320-48f2-8620-826d9011ed43', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '体調不良で早退したい場合、上司に伝える最も適切な表現はどれですか？', '「申し訳ございませんが、体調がすぐれないため、早退させていただいてもよろしいでしょうか」は体調不良を理由に早退を申し出る丁寧な表現です。許可を求める形にするのがマナーです。', 2, 12, '中級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('27cd90fc-d5b7-4e01-9011-083648ae7cfe', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議で新しいアイデアを提案する際、最も適切な表現はどれですか？', '「一つご提案がございますが、ご検討いただけますでしょうか」は提案を切り出す際の丁寧な表現です。提案を押し付けず、検討を依頼する姿勢が大切です。', 2, 13, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('0e9de58c-1605-4310-9d47-29a5602f6e5e', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議で振られたタスクを引き受ける際、最も適切な表現はどれですか？', '「承知いたしました。〇〇までに対応いたします」はタスクを引き受け、期限を明示する丁寧な表現です。「承知いたしました」は「わかりました」の謙譲表現です。', 2, 14, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('cdba75ac-ef46-40fa-97e5-2193f1d073a6', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議の時間が押している場合、進行役として最も適切な発言はどれですか？', '「お時間が迫っておりますので、残りの議題は次回に持ち越させていただいてもよろしいでしょうか」は時間切れを丁寧に伝え、参加者の合意を得る表現です。', 2, 15, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('ed55ca74-a48f-408a-ad44-70c994bc0295', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議で参加者に意見を求める際、最も適切な表現はどれですか？', '「〇〇さん、この件について何かご意見はございますか」は特定の参加者に意見を求める丁寧な表現です。名前を呼んでから質問するのが基本です。', 2, 16, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('5cd7473a-a121-4cb9-9818-6bec101059e7', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', 'オンライン会議で相手の音声が途切れた場合、最も適切な表現はどれですか？', '「恐れ入りますが、音声が途切れておりましたので、もう一度お願いできますでしょうか」はオンライン会議でのトラブル対応の丁寧な表現です。リモートワークが増えた現在、重要な表現です。', 2, 17, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('7e3e90cf-a896-46b2-94e1-272581bb8d8e', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議の最後に決定事項を確認する際、最も適切な表現はどれですか？', '「本日の決定事項を確認させていただきます」は会議の締めくくりで決定事項を振り返る際の定型表現です。認識の齟齬を防ぐために重要なプロセスです。', 2, 18, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('ede4cfc6-0091-4538-a81b-ea6e5318daf6', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議で画面共有をして資料を見せる際、最も適切な表現はどれですか？', '「画面を共有させていただきます。資料の〇ページをご覧ください」は画面共有時の丁寧な案内表現です。IT業界のオンライン会議で頻繁に使います。', 2, 19, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('beb8685b-dc1b-437b-a31c-24a858efbb63', 'b3000001-0000-0000-0000-000000000001', 'multiple_choice', '会議の最後に次回の打ち合わせ予定を確認する際、最も適切な表現はどれですか？', '「次回の打ち合わせは〇月〇日を予定しておりますが、ご都合いかがでしょうか」は次回日程を確認する丁寧な表現です。相手の都合を確認する姿勢が大切です。', 2, 20, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('4a7cb3b2-01b3-4b41-ab94-03245d07adc9', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントとの打ち合わせ後にお礼のメールを送る際、最も適切な書き出しはどれですか？', '「本日はお忙しい中、お打ち合わせのお時間をいただき、誠にありがとうございました」は打ち合わせ後のお礼メールの定型表現です。相手の忙しさへの配慮を示しています。', 2, 13, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('e7e66fbd-1ed3-4255-a9c8-74e5b5aeb72c', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントからの技術的な質問にすぐ回答できない場合、最も適切な表現はどれですか？', '「確認の上、本日中にご回答させていただきます」はすぐに回答できない場合に回答期限を明示する丁寧な表現です。期限を切ることで信頼を維持します。', 2, 14, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('b5a4409c-86e5-4d74-98e3-ddbd068939f5', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', '本番環境で障害が発生した際、クライアントへの第一報として最も適切な表現はどれですか？', '「緊急のご連絡でございます。現在、〇〇システムにおいて障害が発生しております。現在、原因の特定と復旧に全力で取り組んでおります」は障害発生時の第一報として適切な表現です。状況と対応状況を簡潔に伝えることが重要です。', 2, 15, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('0932ece5-58b5-4af0-81dd-a52f68142c26', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントに追加開発の費用が発生することを伝える際、最も適切な表現はどれですか？', '「恐れ入りますが、こちらの追加機能については別途お見積もりとなりますが、よろしいでしょうか」は追加費用の発生を丁寧に伝える表現です。クッション言葉「恐れ入りますが」で柔らかく伝えています。', 2, 16, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('6756cf14-1332-46ca-811f-3e1d3eec921b', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントに成果物を納品する際、最も適切な表現はどれですか？', '「成果物を納品させていただきます。ご確認の上、ご不明な点やご要望がございましたら、お知らせいただけますと幸いです」は納品時の丁寧な表現です。確認依頼とフィードバック受付を含んでいます。', 2, 17, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d6c3ee7e-692c-493f-8017-41d10715267b', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントに保守契約の更新について連絡する際、最も適切な表現はどれですか？', '「保守契約の更新時期が近づいてまいりましたので、ご連絡させていただきました」は契約更新の連絡を丁寧に切り出す表現です。「まいりました」は「きました」の丁重語です。', 2, 18, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('c4aacd14-7e55-4485-87ae-43947c73086b', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'クライアントの要望が技術的に難しい場合、代替案を提示する最も適切な表現はどれですか？', '「ご要望の実装は技術的に難しい状況でございますが、代替案としてこちらの方法をご提案させていただけますでしょうか」は要望を否定せず代替案を提案する丁寧な表現です。', 2, 19, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('6b04f81c-fae0-4eb8-a3a0-f5f7e5a3bd5d', 'b3000002-0000-0000-0000-000000000002', 'multiple_choice', 'プロジェクト完了をクライアントに報告する際、最も適切な表現はどれですか？', '「プロジェクトが無事完了いたしましたことをご報告申し上げます。ご支援いただき、誠にありがとうございました」はプロジェクト完了報告の丁寧な表現です。クライアントへの感謝を忘れないことが大切です。', 2, 20, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('3dcb577f-2d28-4836-9865-ed0bc5dbf487', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '会議室を予約したいことを管理部門に伝える際、最も適切な表現はどれですか？', '「お手数ですが、〇月〇日の〇時から会議室Aの予約をお願いできますでしょうか」は会議室予約を依頼する丁寧な表現です。「お手数ですが」は相手に手間をかけることへの配慮を示すクッション言葉です。', 2, 13, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('4c2c1977-b207-44db-b8d1-89a1e7dda267', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '上司に作成した資料の確認を依頼する際、最も適切な表現はどれですか？', '「お手すきの際に、こちらの資料をご確認いただけますでしょうか」は上司に資料確認を依頼する丁寧な表現です。「お手すき」は「手が空いている」の尊敬語で、相手のスケジュールを配慮しています。', 2, 14, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('e7a47a2d-0707-432b-b811-40e7744a1267', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '複数のタスクを抱えている場合、上司に優先順位を確認する最も適切な表現はどれですか？', '「現在、〇〇と△△のタスクを抱えておりますが、優先順位についてご指示いただけますでしょうか」は上司に優先順位の指示を仰ぐ丁寧な表現です。現状を説明した上で指示を求めるのがポイントです。', 2, 15, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('5392025e-0691-4b2f-bb5e-e24b4aa74525', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '上司に相談したいことがある場合、切り出す最も適切な表現はどれですか？', '「お時間をいただけますでしょうか。ご相談したいことがございます」は上司に相談を持ちかける際の丁寧な表現です。まず時間を確保できるか確認するのがマナーです。', 2, 16, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('4fb82b1a-ecd0-4c30-be33-beedcf1e967b', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '先輩にコードレビューをしてもらった後、お礼を述べる最も適切な表現はどれですか？', '「丁寧なレビューをいただき、ありがとうございます。いただいたフィードバックを反映いたします」はレビュー後のお礼として適切な表現です。感謝とアクションの両方を伝えることが重要です。', 2, 18, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('9d32d09c-191c-4952-8e5d-d206cd0cffdf', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '先輩にコードレビューを依頼する際、最も適切な表現はどれですか？', '「お忙しいところ恐縮ですが、プルリクエストのレビューをお願いできますでしょうか」はコードレビュー依頼の丁寧な表現です。「恐縮ですが」は「恐れ入りますが」と同様のクッション言葉です。', 2, 17, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000501', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「進捗報告」의 한국어 의미는?', '進捗報告(しんちょくほうこく)는 프로젝트의 진행 상황을 보고하는 진척 보고입니다.', 1, 1, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000508', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「課題管理」가 의미하는 것은?', '課題管理(かだいかんり)는 프로젝트에서 발생하는 이슈/과제를 추적 관리하는 것입니다.', 1, 8, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000502', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「納期」를 한국어로 무엇이라 하는가?', '納期(のうき)는 프로젝트나 작업의 완료 기한인 납기입니다.', 1, 2, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000504', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「見積もり」의 한국어 의미는?', '見積もり(みつもり)는 비용이나 작업량을 미리 산정하는 견적입니다.', 1, 4, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000505', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「工数」가 의미하는 것은?', '工数(こうすう)는 작업에 필요한 노력의 양을 나타내는 공수(인월, 인일)입니다.', 1, 5, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000506', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「スケジュール」을 일본 IT 현장에서 어떻게 활용하는가?', 'スケジュール(Schedule)는 프로젝트 일정 관리를 위해 사용되며, 간트 차트 등으로 관리합니다.', 1, 6, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000507', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「リリース」의 한국어 의미는?', 'リリース(Release)는 개발 완료된 시스템이나 기능을 공개/배포하는 릴리스입니다.', 1, 7, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000509', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「ステークホルダー」의 한국어 의미는?', 'ステークホルダー(Stakeholder)는 프로젝트에 이해관계가 있는 사람/조직인 이해관계자입니다.', 1, 9, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d0000002-0000-4000-a000-000000000510', 'd0000001-0000-4000-a000-000000000005', 'multiple_choice', '「ウォーターフォール」이 의미하는 개발 방법론은?', 'ウォーターフォール(Waterfall)는 순차적으로 단계를 진행하는 폭포수 모델 개발 방법론입니다.', 1, 10, '初級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('c6073824-cb3b-45a0-ab85-60f7a0d31839', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', 'タスクが終わらず残業したい場合、上司に許可を求める最も適切な表現はどれですか？', '「〇〇の対応が残っておりますので、本日残業させていただいてもよろしいでしょうか」は残業の許可を求める丁寧な表現です。残業理由を明示した上で許可を求めるのがポイントです。', 2, 19, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('2cdd78cc-2a2e-451a-b339-dcec6c77dcd6', 'b3000003-0000-0000-0000-000000000003', 'multiple_choice', '「ホウレンソウ」における「連絡」と「相談」の違いとして最も正しい説明はどれですか？', '「連絡」は事実やスケジュールなどの情報を関係者に伝えること、「相談」は判断に迷う事項について上司や先輩の意見を求めることです。この違いを理解することは日本の職場で非常に重要です。', 2, 20, '上級', 'business_expression', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('51cbf064-7036-40de-a2e6-0b6c1b1a19e5', 'b1000001-0000-0000-0000-000000000006', 'multiple_choice', '「損益」의 의미로 올바른 것은?', '損益(そんえき)는 ''「損失」と「利益」손익''라는 뜻입니다.', 2, 49, '上級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
