INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('cbc042af-a5eb-42da-b3fd-e47b040eb46a', 'b1000001-0000-0000-0000-00000000000b', 'multiple_choice', '「議事録」의 의미로 올바른 것은?', '議事録(ぎじろく)는 ''회의록''라는 뜻입니다.', 2, 44, '上級', 'vocabulary', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('7cabc491-9a6f-4ca7-8e60-31d5f6e6e5ed', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '「お客様がする」を尊敬語に変換した場合、正しいものはどれですか？', '「する」の尊敬語は「される」または「なさる」です。「いたす」は謙譲語なので、お客様の動作には使えません。', 2, 1, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('24a4aca3-523a-421f-8826-85c10808f1f5', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '「私が資料を見る」を謙譲語に変換した場合、正しいものはどれですか？', '「見る」の謙譲語は「拝見する」です。「ご覧になる」は尊敬語なので、自分の動作には使えません。', 2, 2, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('55909814-bcf7-4b36-89d8-74b6d728d2fa', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '「部長が言った」を尊敬語に変換した場合、正しいものはどれですか？', '「言う」の尊敬語は「おっしゃる」です。「申す」は謙譲語で、自分の動作に使います。', 2, 3, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('5b962c24-d89a-4e27-abce-956b8a1d46a0', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '上司から食事をすすめられた際、「食べる」の謙譲語として正しいものはどれですか？', '「食べる」の謙譲語は「いただく」です。「召し上がる」は尊敬語で、相手の動作に使います。', 2, 4, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('23cbb68f-1f9c-4f83-9e90-156c7f5ef34c', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '次の文のうち、二重敬語（敬語の重複）になっているものはどれですか？', '「お読みになられる」は「お読みになる」（尊敬語）+「〜られる」（尊敬語）で二重敬語です。正しくは「お読みになる」です。', 2, 1, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('27d8ca2e-f3e2-4247-8cbd-ea3da9efaf4f', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '次の文のうち、敬語の使い方が間違っているものはどれですか？', '「私がおっしゃったのは」は自分の動作に尊敬語を使っているため誤りです。正しくは「私が申し上げたのは」です。', 2, 2, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('4b2fd683-ef4f-4d49-993e-3bc8e7fc2bba', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '次の文のうち、いわゆる「バイト敬語」で正しくない表現はどれですか？', '「こちらが資料になります」の「〜になります」は変化を表す表現で、ここでは不適切です。「こちらが資料でございます」が正しい表現です。', 2, 3, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('3a8d0adb-b794-4303-b79d-1fe1ade73c12', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '次の文のうち、「ら抜き言葉」になっているものはどれですか？', '「見れますか」は「見られますか」の「ら」が抜けた形です。ビジネスの場では「見られますか」が正しい表現です。', 2, 4, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('cd449cbc-3e79-44ce-9d35-fb7f9e906840', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '社外の方に自社の部長を紹介する際、正しい表現はどれですか？', '社外の人に自社の上司を紹介する際は、敬称を外して「弊社の部長の田中」のように言います。「田中部長」は社内での呼び方です。', 2, 1, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('db5c5de0-4867-468f-8def-ee8bce643eba', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先とのメールで、「____のご要望に沿えるよう、____一同努力いたします」の空欄に入る正しい組み合わせはどれですか？', '相手の会社は「御社」（口頭）/「貴社」（書面）、自社は「弊社」を使います。メールは書面なので「貴社」と「弊社」が正しい組み合わせです。', 2, 2, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('0d1d7d0c-112e-4f6f-9f83-08a935609132', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '社外の方から電話があり、自社の佐藤課長が不在の場合、正しい応対はどれですか？', '社外の人に対しては自社の人を呼び捨てにし、謙譲語を使います。「佐藤は席を外しております」が正しい表現です。', 2, 3, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('18b00feb-e088-4cbd-acb8-19df652e6980', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先に対して、自社の田中部長の発言を伝える際、正しい表現はどれですか？', '社外に自社上司の発言を伝える際は謙譲語「申す」を使い、敬称もつけません。「田中が申しておりました」が正しい表現です。', 2, 4, '初級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('f12285a5-8987-4827-a050-f61bbacf5904', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '「お客様が明日会社に来る」を尊敬語に変換した場合、正しいものはどれですか？', '「来る」の尊敬語は「いらっしゃる」「お見えになる」「お越しになる」です。「参る」は謙譲語です。', 2, 5, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('995d09a3-2626-49a3-bcd8-af1960394aa0', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '取引先の担当者に「この件を知っていますか」と尋ねる場合、最も適切な表現はどれですか？', '「知る」の尊敬語は「ご存じ」です。相手が知っているかどうかを尋ねる場合は「ご存じですか」を使います。', 2, 6, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('6f915355-810a-429e-a85a-7c5989b5b496', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '上司に質問したい場合、「聞く」の謙譲語として最も適切な表現はどれですか？', '「聞く」の謙譲語は「伺う」です。「お聞きになる」は尊敬語で、相手の動作に使います。', 2, 7, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('e857d9c5-9395-4bad-a0da-815335309fe4', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '取引先から送られた報告書を読んだことを伝える場合、最も適切な表現はどれですか？', '「読む」の謙譲語は「拝読する」です。相手が書いたもの・送ったものを読む場合に使う格式の高い表現です。', 2, 8, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('50cb65cf-61f7-4970-872c-18d1785ff69c', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '上司から資料を受け取った場合、「もらう」の謙譲語として正しいものはどれですか？', '「もらう」の謙譲語は「いただく」です。上司や目上の人から何かを受け取る際に使います。', 2, 9, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('7b5c3c5a-9712-4e9f-8351-68269bf2d750', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '取引先の社長に初めて会った際、「会えてうれしい」を最も適切に表現したものはどれですか？', '「会う」の謙譲語は「お目にかかる」です。「お目にかかれて光栄です」は格式の高い挨拶表現です。', 2, 10, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('eb82a413-7a9f-4eba-9781-ab65d823a2e8', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '電話で自分が在席していることを伝える場合、「いる」の謙譲語として正しいものはどれですか？', '「いる」の謙譲語は「おる」です。自分の状態を謙遜して伝える表現です。', 2, 11, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('b15c10da-8491-4901-b1cd-6aea8f89bb2e', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '「お客様が資料を使う」を「お/ご〜になる」パターンで尊敬語にした場合、正しいものはどれですか？', '「使う」は和語なので「お」をつけて「お使いになる」とします。漢語には「ご」をつけるのが基本ルールです。', 2, 12, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('327aebb7-d069-4f52-a6e4-eb73fe4fc2d0', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '現在の確認をする際、正しい表現はどれですか？', '「よろしかったでしょうか」は過去形で、現在の確認には不適切です。「よろしいでしょうか」が正しい現在形の表現です。', 2, 5, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('83e11d26-ded1-4d80-84e1-22c47d76330f', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '上司からの指示を受けた際、最もビジネスに適した返答はどれですか？', '「承知いたしました」「かしこまりました」は上司や目上の人への返答として最も適切です。「了解しました」は同等の立場向けです。', 2, 6, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('323d2841-55e8-4e13-bf4b-048940ce2756', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '上司の説明に対して同意を示す際、最も適切な表現はどれですか？', '「なるほどですね」は文法的に不自然で、目上の人に使うと失礼です。「おっしゃる通りです」が適切な同意表現です。', 2, 7, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('0e22c895-f2b0-4cd4-9caf-df5af912f2f8', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '次の「お/ご」の使い方で、間違っているものはどれですか？', '外来語には「お/ご」をつけないのが原則です。「おコーヒー」は不適切で、「コーヒー」とそのまま使います。', 2, 8, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('31d4db5e-0f65-46bd-84b8-afe0bb9943b6', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '「お客様が来ました」を敬語に直す場合、正しいものはどれですか？', '「参る」は謙譲語で自分の動作に使います。お客様の動作には尊敬語「いらっしゃる」を使うのが正しいです。', 2, 9, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('c035ae60-c2f6-4539-aa83-0ffdb975ebfe', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '取引先に迷惑をかけた際の謝罪として、最も適切な表現はどれですか？', '取引先への謝罪には「申し訳ございません」が最も適切です。「すみません」は日常的すぎてビジネスでは格式が足りません。', 2, 10, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('126abada-c897-4b59-b3cd-988ddce9e5de', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '次の「させていただく」の使い方で、不適切なものはどれですか？', '「させていただく」は相手の許可が必要な場面で使うのが原則です。「拝見する」だけで十分謙譲の意味があるため、「拝見させていただく」は過剰です。', 2, 11, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('98a9d727-c4f0-4ee3-b87c-bdeb38e6204b', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '上司に情報を伝える際、最も適切な表現はどれですか？', '「教えてあげます」は恩恵を与えるニュアンスがあり、目上の人に使うと失礼です。「お伝えいたします」が適切な謙譲表現です。', 2, 12, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('01937a63-30aa-4da9-ab6f-bee9f89cbae5', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '社内の同僚に送るメールの書き出しとして、最も適切なものはどれですか？', '社内メールは「お疲れ様です」で始めるのが一般的です。「いつもお世話になっております」は社外向けの挨拶です。', 2, 5, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('12884872-e7c4-4382-844e-c6cacde8cbfd', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先に自社の担当者を紹介する際、正しい表現はどれですか？', '「弊社の担当の鈴木がご説明いたします」は、弊社（謙遜）+呼び捨て+謙譲語の正しいウチ・ソトパターンです。', 2, 6, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('44eedbb9-29ff-49c0-8f88-4b576a83b573', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先との電話で、「弊社の担当が午後に____」の空欄に入る正しい表現はどれですか？', '自社の人の移動には謙譲語「参る」を使います。「いらっしゃる」は尊敬語で、相手側の動作に使います。', 2, 7, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('8f35791a-2140-46e4-b7c1-312b15996f9a', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '他社の人に自分の部署の同僚を紹介する場合、「ウチ」の範囲はどこまでですか？', '他社の人と話す場合、自社全体が「ウチ」になります。自分の部署の同僚はもちろん、他部署の上司も「ウチ」として扱います。', 2, 8, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('e61c9966-8684-4088-b75e-44471e82956b', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '社内会議では「田中部長がおっしゃった通り」と言いますが、取引先の前で同じ内容を伝える場合、正しい表現はどれですか？', '取引先の前では自社の上司も「ウチ」なので、敬称を外し謙譲語を使います。「弊社の田中が申しました通り」が正しい表現です。', 2, 9, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('d97673f0-a49c-41a8-9f35-9a46e1a2cee9', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先に送るメールの書き出しとして、最も適切なものはどれですか？', '社外メールでは「いつもお世話になっております」が最も一般的な書き出しです。「お疲れ様です」は社内向けの挨拶です。', 2, 10, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('f7ad59c4-77ab-4bf9-9348-42ece833a63f', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', 'お客様の前で自社のエンジニア佐藤を紹介する際、正しい表現はどれですか？', 'お客様の前では同僚も「ウチ」なので呼び捨てにし、「でございます」「おります」等の謙譲・丁重表現を使います。', 2, 11, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('02611999-f55e-4ec0-8a6c-dda4ccd75a40', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先の担当者が確認してくれたことを伝える場合、正しい表現はどれですか？', '取引先（ソト）の行為には尊敬語を使います。「ご確認くださいました」「ご確認いただきました」が適切です。', 2, 12, '中級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('904c5fd5-46f8-4899-ac1b-2559c3221502', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '「私がお客様を案内する」を「お/ご〜する」パターンで謙譲語にした場合、正しいものはどれですか？', '「案内する」は漢語なので「ご」をつけて「ご案内する」「ご案内いたす」とします。', 2, 13, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('676f7397-23b3-4175-812a-93b2b7267372', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '会議で自分の意見を述べる際、「私もそう思います」を謙譲語で表現した場合、最も適切なものはどれですか？', '「思う」の謙譲語は「存じる」です。「存じます」は自分の考えを謙遜して述べる丁寧な表現です。', 2, 14, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('6bc84fcb-3579-4b95-9274-e3d0180d29ec', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '来客に会議室の場所を案内する際、最も丁寧な表現はどれですか？', '「ございます」は「あります」の最も丁寧な形です。来客やお客様に対して使う格式の高い丁寧語です。', 2, 15, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('473fd455-357a-470c-9d4d-0bef95ab6d3b', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '取引先に資料を渡す際、「あげる」の謙譲語として正しいものはどれですか？', '「あげる」の謙譲語は「差し上げる」です。相手に何かを提供・贈呈する際に使います。', 2, 16, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('bed36c51-9b74-42e9-a243-203e93d259a3', 'b4000001-0000-0000-0000-000000000001', 'multiple_choice', '上司に書類を確認してもらいたい場合、「お/ご〜いただく」パターンで最も適切な表現はどれですか？', '「確認」は漢語なので「ご確認いただけますでしょうか」が正しい形です。依頼形として非常に丁寧な表現です。', 2, 17, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('9fcab7a7-1316-4064-b6e3-4b23c7fc4cb4', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '上司が外出から戻ってきた際、最も適切な声かけはどれですか？', '「ご苦労様です」は目上が目下に使う表現です。上司に対しては「お疲れ様です」を使うのがマナーです。', 2, 13, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('fa13f8d0-b15c-4d00-a5b9-16c45d727e82', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '取引先に質問する際、最もビジネスにふさわしい表現はどれですか？', '「ちょっとお聞きしたいんですけど」は「ちょっと」「〜んですけど」がカジュアルすぎます。「少々お伺いしたいのですが」が適切です。', 2, 14, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('4cf26be2-ee44-4e90-8a77-b7584f664c73', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '次のうち、二重敬語になっていない正しい表現はどれですか？', '「ご覧になる」は「見る」の正しい尊敬語です。「おっしゃられる」「お召し上がりになられる」「ご覧になられる」はいずれも二重敬語です。', 2, 15, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('6d4a4074-14b8-4abe-aa61-2ac0d9b10a4b', 'b4000002-0000-0000-0000-000000000002', 'multiple_choice', '注文を確認する際、「ご注文は以上で____」の空欄に入る正しい表現はどれですか？', '現在の注文確認には現在形を使います。「よろしかったですか」は過去形で文法的に不適切です。「よろしいでしょうか」が正しい表現です。', 2, 16, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('948617e6-c9f9-4fad-8d8c-c1815bb5d869', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '他社と打ち合わせ中に、「この件は____で対応いたします」と自分の部署を指す場合、正しい表現はどれですか？', '自社の部署を指す場合は「当部署」「弊部署」を使います。「私どもの部署」も使えます。', 2, 13, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('c89ee2de-6d80-47ca-8e89-6389d5296e45', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先から電話があり、担当の山田が不在の場合、折り返しの連絡を提案する最も適切な表現はどれですか？', '自社の人は呼び捨て+謙譲語が基本です。「山田が戻り次第、折り返しお電話いたします」が正しい表現です。', 2, 14, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('1c297f0d-31c8-4fce-aa48-adb9d71f9af4', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '次のうち、敬語の使い方がすべて正しい文はどれですか？', '「部長がおっしゃった資料を拝見いたしました」は、部長の動作に尊敬語「おっしゃる」、自分の動作に謙譲語「拝見する」を正しく使い分けています。', 2, 15, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('ea2958d0-8c44-4641-873d-302200d4b246', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', '取引先への電話で「担当の鈴木に確認して、折り返し連絡します」を敬語で伝える場合、最も適切な表現はどれですか？', '自社の鈴木は呼び捨て+謙譲語、自分の行動も謙譲語を使います。「担当の鈴木に確認いたしまして、折り返しご連絡いたします」が正しい表現です。', 2, 16, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES ('65657640-3fdf-431e-8316-cf61fe11a8b5', 'b4000003-0000-0000-0000-000000000003', 'multiple_choice', 'お客様が来社された際、会議室にご案内する表現として最も適切なものはどれですか？', '「ご案内いたします」は自分の動作を謙譲語で表現し、「どうぞこちらへ」は丁寧語で案内する適切な組み合わせです。', 2, 17, '上級', 'keigo', true) ON CONFLICT (id) DO NOTHING;
